CREATE OR REPLACE FUNCTION public.validate_event_staff_organization()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  event_org uuid;
  member_org uuid;
begin

  select organization_id
  into event_org
  from public.events
  where id = new.event_id;

  select organization_id
  into member_org
  from public.organization_members
  where id = new.organization_member_id;

  if event_org is null then
    raise exception 'Evento inexistente';
  end if;

  if member_org is null then
    raise exception 'Miembro inexistente';
  end if;

  if event_org <> member_org then
    raise exception
      'El miembro y el evento pertenecen a organizaciones diferentes';
  end if;

  return new;
end;
$function$
